package PerlComparison::Sequences;
use strict;
use warnings;
sub array {
    ref($_[0]) eq 'ARRAY' or die "SequenceType\n";
    return $_[0];
}
sub callable {
    ref($_[0]) eq 'CODE' or die "CallableType\n";
    return $_[0];
}
sub truth {
    my ($value) = @_;
    defined($value) && !ref($value) && $value =~ /\A-?[0-9]+\z/
        or die "PredicateType\n";
    return $value != 0;
}
sub map_values {
    my ($items, $transform) = @_;
    array($items); callable($transform);
    my @out;
    for my $item (@$items) {
        my $value = $transform->($item);
        push @out, $value;
    }
    return \@out;
}
sub filter_values {
    my ($items, $accepts) = @_;
    array($items); callable($accepts);
    my @out;
    for my $item (@$items) {
        push @out, $item if truth($accepts->($item));
    }
    return \@out;
}
sub fold_values {
    my ($items, $seed, $step) = @_;
    array($items); callable($step);
    my $value = $seed;
    for my $item (@$items) {
        $value = $step->($value, $item);
    }
    return $value;
}
sub scan_values {
    my ($items, $seed, $step) = @_;
    array($items); callable($step);
    my $value = $seed;
    my @out = ($seed);
    for my $item (@$items) {
        $value = $step->($value, $item);
        push @out, $value;
    }
    return \@out;
}
sub any_value {
    my ($items, $accepts) = @_;
    array($items); callable($accepts);
    for my $item (@$items) {
        return 1 if truth($accepts->($item));
    }
    return 0;
}
sub all_values {
    my ($items, $accepts) = @_;
    array($items); callable($accepts);
    for my $item (@$items) {
        return 0 unless truth($accepts->($item));
    }
    return 1;
}
sub flat_map {
    my ($items, $next) = @_;
    array($items); callable($next);
    my @out;
    for my $item (@$items) {
        my $part = array($next->($item));
        for my $value (@$part) {
            push @out, $value;
        }
    }
    return \@out;
}
1;

package PerlComparison::Ranges;
use strict;
use warnings;
sub array {
    ref($_[0]) eq 'ARRAY' or die "SequenceType\n";
    return $_[0];
}
sub checked_index {
    my ($value) = @_;
    defined($value) && !ref($value) && $value =~ /\A[0-9]+\z/
        or die "ReceiverIndex\n";
    return 0 + $value;
}
sub select_values {
    my ($source, $indices) = @_;
    array($source); array($indices);
    my @checked;
    for my $value (@$indices) {
        my $at = checked_index($value);
        $at < @$source or die "ReceiverIndex\n";
        push @checked, $at;
    }
    my @out;
    push @out, $source->[$_] for @checked;
    return \@out;
}
sub replace_range {
    my ($target, $begin, $end, $values) = @_;
    array($target); array($values);
    $begin = checked_index($begin); $end = checked_index($end);
    $begin <= $end && $end <= @$target or die "ReceiverIndex\n";
    my @staged = @$values;
    my @ready;
    for (my $i = 0; $i < $begin; ++$i) { push @ready, $target->[$i] }
    push @ready, @staged;
    for (my $i = $end; $i < @$target; ++$i) { push @ready, $target->[$i] }
    @$target = @ready;
    return $target;
}
sub splice_values {
    my ($target, $begin, $end, $values) = @_;
    array($target); array($values);
    $begin = checked_index($begin); $end = checked_index($end);
    $begin <= $end && $end <= @$target or die "ReceiverIndex\n";
    my @removed;
    for (my $i = $begin; $i < $end; ++$i) { push @removed, $target->[$i] }
    replace_range($target, $begin, $end, $values);
    return \@removed;
}
1;

package PerlComparison::Ordering;
use strict;
use warnings;
sub arguments {
    my ($items, $operation) = @_;
    ref($items) eq 'ARRAY' or die "SequenceType\n";
    ref($operation) eq 'CODE' or die "CallableType\n";
}
sub integer {
    my ($value) = @_;
    defined($value) && !ref($value) && $value =~ /\A-?[0-9]+\z/
        or die "ComparisonType\n";
    return 0 + $value;
}
sub stable_sort {
    my ($items, $compare) = @_;
    arguments($items, $compare);
    my $current = [@$items];
    my $count = @$current;
    my $scratch = [];
    my $width = 1;
    while ($width < $count) {
        my $start = 0;
        while ($start < $count) {
            my $middle = $width < $count - $start ? $start + $width : $count;
            my $end = $width < $count - $middle ? $middle + $width : $count;
            my ($left, $right, $at) = ($start, $middle, $start);
            while ($at < $end) {
                my $take_left = $right == $end;
                if (!$take_left && $left < $middle) {
                    my $order = integer($compare->($current->[$left], $current->[$right]));
                    $take_left = $order <= 0;
                }
                $scratch->[$at++] = $take_left ? $current->[$left++] : $current->[$right++];
            }
            $start = $end;
        }
        ($current, $scratch) = ($scratch, $current);
        $width = $width > $count - $width ? $count : $width + $width;
    }
    return $current;
}
sub stable_unique {
    my ($items, $same) = @_;
    arguments($items, $same);
    my @out;
    ITEM: for my $item (@$items) {
        for my $previous (@out) {
            next ITEM if integer($same->($previous, $item)) != 0;
        }
        push @out, $item;
    }
    return \@out;
}
1;

package PerlComparison::Groups;
use strict;
use warnings;
sub group_by {
    my ($items, $key_of, $same_key) = @_;
    ref($items) eq 'ARRAY' or die "SequenceType\n";
    ref($key_of) eq 'CODE' && ref($same_key) eq 'CODE' or die "CallableType\n";
    my @groups;
    for my $item (@$items) {
        my $key = $key_of->($item);
        my $selected;
        for my $group (@groups) {
            my $same = $same_key->($group->{key}, $key);
            defined($same) && !ref($same) && $same =~ /\A-?[0-9]+\z/
                or die "PredicateType\n";
            if ($same != 0) { $selected = $group; last }
        }
        if (!defined $selected) {
            $selected = {key => $key, items => []};
            push @groups, $selected;
        }
        push @{$selected->{items}}, $item;
    }
    return \@groups;
}
1;

package PerlComparison::Records;
use strict;
use warnings;
use Scalar::Util qw(refaddr reftype blessed);
sub clone_data {
    my ($value, $seen) = @_;
    return $value unless ref $value;
    blessed($value) and die "MergeType\n";
    my $address = refaddr($value);
    return $seen->{$address} if exists $seen->{$address};
    my $kind = reftype($value);
    if ($kind eq 'HASH') {
        my $out = {};
        $seen->{$address} = $out;
        for my $key (keys %$value) { $out->{$key} = clone_data($value->{$key}, $seen) }
        return $out;
    }
    if ($kind eq 'ARRAY') {
        my $out = [];
        $seen->{$address} = $out;
        for my $item (@$value) { push @$out, clone_data($item, $seen) }
        return $out;
    }
    if ($kind eq 'SCALAR' || $kind eq 'REF') {
        my $target;
        my $out = \$target;
        $seen->{$address} = $out;
        $target = clone_data($$value, $seen);
        return $out;
    }
    die "MergeType\n";
}
sub derive_record {
    my ($base, $extension) = @_;
    ref($base) eq 'HASH' && ref($extension) eq 'HASH' or die "MergeType\n";
    my %seen;
    my $model = clone_data($base, \%seen);
    my $extra = clone_data($extension, \%seen);
    for my $key (keys %$extra) { $model->{$key} = $extra->{$key} }
    my %group;
    for my $key (keys %$model) { $group{$key} = $model->{$key} }
    return \%group;
}
1;

package PerlComparison::Resources;
use strict;
use warnings;
sub bracket {
    my ($acquire, $release, $action, @arguments) = @_;
    ref($acquire) eq 'CODE' && ref($release) eq 'CODE' && ref($action) eq 'CODE'
        or die "CallableType\n";
    my ($ready, $resource, $value) = (0);
    my $ok = eval {
        $resource = $acquire->();
        $ready = 1;
        $value = $action->($resource, @arguments);
        1;
    };
    my $failure = $@;
    if ($ready) {
        my $released = eval { $release->($resource); 1 };
        if (!$released) { $failure = $@; $ok = 0 }
    }
    die $failure unless $ok;
    return $value;
}
1;

package PerlComparison::Patterns;
use strict;
use warnings;
sub text {
    my ($source) = @_;
    defined($source) && !ref($source) or die "PatternEncoding\n";
    for my $character (CORE::split //, $source) {
        ord($character) <= 255 or die "PatternEncoding\n";
    }
    return "$source";
}
sub literal {
    return quotemeta(text($_[0]));
}
sub sequence {
    my ($parts) = @_;
    ref($parts) eq 'ARRAY' or die "PatternArgument\n";
    my $source = '';
    for my $part (@$parts) {
        defined($part) && !ref($part) or die "PatternArgument\n";
        $source .= "(?:$part)";
    }
    return $source;
}
sub name {
    my ($name) = @_;
    defined($name) && !ref($name) && $name =~ /\A[A-Za-z_][A-Za-z0-9_]*\z/
        or die "PatternArgument\n";
    return $name;
}
sub capture {
    my ($name, $pattern) = @_;
    $name = name($name);
    defined($pattern) && !ref($pattern) or die "PatternArgument\n";
    return "(?<$name>$pattern)";
}
sub same_as {
    my $name = name($_[0]);
    return "\\k<$name>";
}
sub repeated {
    my ($pattern, $minimum, $maximum, $extend_first) = @_;
    $minimum = 0 unless defined $minimum;
    $extend_first = 1 unless defined $extend_first;
    defined($pattern) && !ref($pattern) or die "PatternArgument\n";
    !ref($minimum) && $minimum =~ /\A[0-9]+\z/ or die "PatternArgument\n";
    if (defined $maximum) {
        !ref($maximum) && $maximum =~ /\A[0-9]+\z/ && $maximum >= $minimum
            or die "PatternArgument\n";
    }
    !ref($extend_first) && $extend_first =~ /\A[01]\z/
        or die "PatternArgument\n";
    return '' if $pattern eq '';
    my $bound = defined($maximum) ? "$minimum,$maximum" : "$minimum,";
    return "(?:$pattern){$bound}" . ($extend_first ? '' : '?');
}
sub then_pattern {
    @_ >= 2 or die "PatternArgument\n";
    return sequence([@_]);
}
sub times {
    my ($pattern, $count) = @_;
    defined($count) or die "PatternArgument\n";
    return repeated($pattern, $count, $count, 1);
}
sub at_least {
    my ($pattern, $minimum) = @_;
    defined($minimum) or die "PatternArgument\n";
    return repeated($pattern, $minimum, undef, 1);
}
sub at_most {
    my ($pattern, $maximum) = @_;
    defined($maximum) or die "PatternArgument\n";
    return repeated($pattern, 0, $maximum, 1);
}
sub optional {
    return repeated($_[0], 0, 1, 1);
}
sub compiled {
    my ($pattern, $whole) = @_;
    defined($pattern) && !ref($pattern) or die "PatternArgument\n";
    my $ready = $whole ? "\\A(?:$pattern)\\z" : "(?:$pattern)";
    my $regex = eval { qr/$ready/ };
    die "PatternArgument: $@" if $@;
    return $regex;
}
sub snapshot {
    my ($source) = @_;
    return {source => $source, begin => $-[0], end => $+[0], captures => {%+}};
}
sub checked_match {
    my ($match) = @_;
    ref($match) eq 'HASH' && ref($match->{captures}) eq 'HASH'
        or die "MatchType\n";
    defined($match->{source}) && !ref($match->{source}) or die "MatchType\n";
    for my $key ('begin', 'end') {
        defined($match->{$key}) && !ref($match->{$key}) && $match->{$key} =~ /\A[0-9]+\z/
            or die "PatternPosition\n";
    }
    $match->{begin} <= $match->{end} && $match->{end} <= length($match->{source})
        or die "PatternPosition\n";
    return $match;
}
sub whole_match {
    my ($source, $pattern) = @_;
    $source = text($source);
    my $regex = compiled($pattern, 1);
    return [0, undef] unless $source =~ /$regex/;
    return [1, snapshot($source)];
}
sub matches {
    return whole_match(@_)->[0];
}
sub each_match {
    my ($source, $pattern) = @_;
    $source = text($source);
    my $regex = compiled($pattern, 0);
    my $finished = 0;
    pos($source) = 0;
    return sub {
        return undef if $finished;
        if ($source =~ /$regex/gc) {
            return snapshot($source);
        }
        $finished = 1;
        return undef;
    };
}
sub matched_text {
    my $match = checked_match($_[0]);
    return substr($match->{source}, $match->{begin}, $match->{end} - $match->{begin});
}
sub capture_text {
    my ($match, $name) = @_;
    checked_match($match);
    $name = name($name);
    return [0, undef] unless exists $match->{captures}{$name};
    return [1, $match->{captures}{$name}];
}
sub replace_all {
    my ($source, $pattern, $replacement) = @_;
    $source = text($source);
    my $callback = ref($replacement) eq 'CODE';
    $replacement = text($replacement) unless $callback;
    my $next = each_match($source, $pattern);
    my ($out, $copied_until) = ('', 0);
    while (my $match = $next->()) {
        $out .= substr($source, $copied_until, $match->{begin} - $copied_until);
        my $insert = $callback ? text($replacement->($match)) : $replacement;
        $out .= $insert;
        $copied_until = $match->{end};
    }
    return $out . substr($source, $copied_until);
}
sub split_parts {
    my ($source, $pattern) = @_;
    $source = text($source);
    my $next = each_match($source, $pattern);
    my @out;
    my $copied_until = 0;
    while (my $match = $next->()) {
        push @out, substr($source, $copied_until, $match->{begin} - $copied_until);
        $copied_until = $match->{end};
    }
    push @out, substr($source, $copied_until);
    return \@out;
}
1;
